const now = new Date();
const endDate = new Date(now);
endDate.setDate(endDate.getDate() - 1);
const startDate = new Date(now);
startDate.setDate(startDate.getDate() - 90);
const fmt = d => d.toISOString().split('T')[0];
return [{ json: { gsc_query_json: JSON.stringify({ startDate: fmt(startDate), endDate: fmt(endDate), dimensions: ['query'], rowLimit: 2500, dataState: 'final' }) } }];

const gscData = $('GSC Query').item.json;
const serpData = $('SerpAPI').item.json;
const blogResp = $('Leer Blog Sheet').first().json;
const blogVals = (blogResp.values || []).slice(1);
const existingKeywords = blogVals.map(row => (row[0] || '').toLowerCase().trim()).filter(k => k);

const gscQueries = (gscData.rows||[])
  .filter(r=>(r.impressions||0)>=3)
  .sort((a,b)=>(b.impressions||0)-(a.impressions||0))
  .map(r=>'"'+r.keys[0]+'" (pos:'+(r.position||0).toFixed(1)+', imp:'+r.impressions+')')
  .slice(0,60).join('\n');
const paa = (serpData.related_questions||[]).map(q=>q.question).join('\n');
const related = (serpData.related_searches||[]).map(s=>s.query).join('\n');

const systemMsg = 'Eres especialista en SEO y contenido editorial para Ferretería Ya, blog de referencia sobre tutoriales DIY, guías de compra y mantenimiento del hogar en Colombia. Generas ideas de blog con demanda real y potencial de posicionamiento en Google Colombia, alineadas con el tono "Asesor de Bricolaje" (entusiasmo práctico, claridad técnica, sin jerga corporativa).';

const userMsg = 'Genera 15 ideas de contenido para el BLOG de Ferretería Ya.\n\n' +
  'KEYWORDS YA EN EL BLOG (NO repetir — verificar similitud Jaccard ≥50%):\n' + (existingKeywords.slice(0,150).join('\n')||'(Sin datos — blog vacío)') +
  '\n\nQUERIES REALES GSC (últimos 90 días, ≥3 impresiones):\n' + (gscQueries||'(Sin datos de GSC — sitio nuevo, GSC todavía no tiene historial)') +
  '\n\nGENTE TAMBIÉN PREGUNTA (PAA Google Colombia):\n' + (paa||'(Sin datos)') +
  '\n\nBÚSQUEDAS RELACIONADAS:\n' + (related||'(Sin datos)') +
  '\n\nINSTRUCCIONES:' +
  '\n- Generá EXACTAMENTE 15 ideas de blog útiles para DIYers, maestros de obra y dueños de hogar en Colombia' +
  '\n- Prioriza queries reales de GSC/PAA con oportunidad real de ranking' +
  '\n- Descarta cualquier keyword con ≥50% palabras significativas iguales a alguna existente' +
  '\n- Intención: 60% Tutoriales DIY ("cómo instalar/reparar/hacer X"), 25% Guías de compra ("mejor X / qué X comprar"), 15% Mantenimiento ("cuándo cambiar / cómo limpiar")' +
  '\n- Cubrí variedad de los 5 nichos: Herramientas, Materiales, Plomería, Electricidad, Jardín' +
  '\n- Incluí modificadores de ciudad cuando aporten ("en Bogotá", "en Medellín") en al menos 3-4 ideas' +
  '\n- Prioridad ALTA para: queries GSC con posición 11-30, o PAA con keywords transaccionales claras' +
  '\n\nFORMATO DE RESPUESTA — JSON ESTRICTO:' +
  '\n{"blog_ideas":[' +
  '\n  {' +
  '\n    "keyword":"cómo instalar una llave de paso en el baño",' +
  '\n    "nicho":"Plomería y Sanitarios",  // exactamente uno de: Herramientas y Equipos | Materiales y Acabados | Plomería y Sanitarios | Electricidad e Iluminación | Jardín y Exteriores' +
  '\n    "pais":"Colombia",  // Colombia | Bogotá | Medellín | General' +
  '\n    "audiencia":"DIYer principiante",  // ej: DIYer principiante | Maestro de obra | Ama de casa | Constructor independiente' +
  '\n    "intencion":"Informacional",  // Informacional | Comercial | Transaccional' +
  '\n    "prioridad":"Alta",  // Alta | Media | Baja' +
  '\n    "fuente":"PAA"  // GSC | PAA | Relacionadas | GPT' +
  '\n  }' +
  '\n]}';

const body = {
  model:'gpt-4o',
  response_format:{type:'json_object'},
  max_tokens:4000,
  messages:[{role:'system',content:systemMsg},{role:'user',content:userMsg}]
};
return [{json:{gpt_body_json:JSON.stringify(body),existingKeywords}}];

const raw = $input.item.json.choices?.[0]?.message?.content || '';
const prev = $('Construir Prompt GPT').item.json;
const existingKeywords = prev.existingKeywords || [];

let ideas;
try { ideas = JSON.parse(raw); } catch(e) { throw new Error('Ideas parse error: ' + raw.substring(0,300)); }

function jaccard(a, b) {
  const stop = new Set(['de','la','el','en','y','para','un','una','con','del','los','las','que','mi','su','es','se','al','como','si','lo','le']);
  const w = s => new Set(s.toLowerCase().split(/\s+/).filter(t=>t.length>2&&!stop.has(t)));
  const wa=w(a), wb=w(b);
  if(!wa.size||!wb.size) return 0;
  const inter=[...wa].filter(t=>wb.has(t)).length;
  return inter/new Set([...wa,...wb]).size;
}

const rawBlog = ideas.blog_ideas || [];

const filteredBlog = rawBlog.filter(idea => {
  const kw = (idea.keyword||'').toLowerCase().trim();
  return kw && !existingKeywords.some(ex=>jaccard(kw,ex)>=0.5);
});

// Estructura para Sheet Blog: 13 columnas A-M
const blogValues = filteredBlog.map(idea => [
  idea.keyword||'',
  'Pendiente',
  idea.prioridad||'Media',
  idea.nicho||'',
  idea.pais||'Colombia',
  idea.audiencia||'',
  idea.intencion||'Informacional',
  '', // url_post
  '', // wordcount
  '', // posicion_gsc
  '', // fecha_objetivo
  '', // fecha_social
  ''  // fecha_reoptimizado
]);

const blog_ideas_json = JSON.stringify({values:blogValues});

const summary = '\u{1F4A1} *Ideas generadas — Ferretería Ya* ✅\n\n' +
  '\u{1F4DD} *Blog:* '+filteredBlog.length+' nuevas' +
  ' ('+(rawBlog.length-filteredBlog.length)+' descartadas por similitud)\n\n' +
  '_Añadidas al Sheet con estado=Pendiente para tu aprobación._';

return [{json:{blog_ideas_json,blog_count:filteredBlog.length,summary}}];
